{
  "selections": [
    {
      "trait_id": "/core_belief/core_belief_statement",
      "background_ids": ["/childhood_data", "/situations/1"],
      "relevance": "상담사가 '괜찮지 않은 모습을 보이면 실망해서 떠날 것 같다'는 내담자의 진술을 반영하고, '괜찮은 모습만 보여야 한다는 긴장'을 질문함. 이는 '사람들이 진짜 나를 알면 결국 떠날 것이다'라는 핵심 신념과 직접 연결됨. 배경으로는 연인이 '무슨 생각을 하는지 모르겠다'고 말한 상황(상황 사례 1)이 해당 신념이 활성화된 계기이며, 어릴 적 부모가 감추도록 요구한 경험(성장 경험)이 이 신념의 기원임."
    },
    {
      "trait_id": "/intermediate_beliefs/rule",
      "background_ids": ["/childhood_data"],
      "relevance": "상담사가 '괜찮은 모습만 보여야 한다는 긴장이 매일 쌓여온 건 아닌지' 질문한 것은 '언제나 괜찮고 문제없는 모습만 보여줘야 한다'는 규칙을 직접 가리킴. 어릴 적 부모가 힘들어하는 모습을 보이면 감추도록 한 경험이 이 규칙의 형성 배경임."
    },
    {
      "trait_id": "/intermediate_beliefs/assumption_negative",
      "background_ids": ["/situations/1"],
      "relevance": "내담자가 '속으로 힘들어하는 모습, 괜찮지 않은 모습을 알면 실망해서 떠날 것 같았다'고 진술한 것은 '부족하거나 힘든 모습을 보이면 사람들은 실망해서 떠날 것이다'라는 부정적 가정과 정확히 일치함. 해당 상황 사례가 이 가정이 실제 관계에서 작동한 예임."
    },
    {
      "trait_id": "/intermediate_beliefs/attitude",
      "background_ids": ["/situations/1"],
      "relevance": "내담자가 '진짜 모습을 눈치챈 것 같아서 떠날 것 같았다'고 말한 것은 '약점이나 부족한 모습, 진짜 감정을 들키는 것은 끔찍한 일이다'라는 태도와 연결됨. 연인의 한마디에 두려움이 촉발된 것이 그 예."
    },
    {
      "trait_id": "/coping_strategies/1",
      "background_ids": ["/childhood_data", "/situations/3"],
      "relevance": "상담사가 '괜찮은 모습만 보여야 하는 긴장이 매일 쌓여온 건 아닌지' 질문한 것은 '사람들 앞에서 항상 밝고 문제없는 모습을 유지하려 애쓰는' 대처 방식과 직접 연결됨. 밤에 과거 실수 장면이 떠오를 때 다음 날 더 밝게 행동하는 패턴(상황 사례 3)이 이 대처의 일상적 작동 방식임."
    },
    {
      "trait_id": "/core_belief/young_schema",
      "background_ids": ["/childhood_data"],
      "relevance": "내담자가 '진짜 모습'을 '괜찮지 않은 모습'으로 규정하고 그것이 드러나면 관계가 끝날 것이라고 느끼는 것은 결함/수치심 스키마의 작동임. 어릴 적 있는 그대로의 모습보다 '괜찮아 보이는 모습'을 보여야만 인정받았던 경험이 이 스키마의 형성 배경임."
    },
    {
      "trait_id": "/core_belief/young_domain",
      "background_ids": ["/situations/1"],
      "relevance": "내담자가 연인의 말 한마디에 '떠날 것 같다'는 두려움을 느낀 것은 단절/거절 영역의 핵심 공포가 활성화된 것임. 상황 사례 1이 해당 영역이 실제 관계에서 작동한 구체적 예임."
    }
  ]
}

